1 | /**
2 |  * BugSleuth frontend — handles form submission, demo loading, and report rendering.
3 |  * API shape matches the run_investigation() response from investigation_service.py.
4 |  */
5 | 
6 | document.addEventListener("DOMContentLoaded", () => {
7 |   const btnInvestigate = document.getElementById("btn-investigate");
8 |   const btnDemo        = document.getElementById("btn-demo");
9 |   if (btnInvestigate) btnInvestigate.addEventListener("click", runInvestigation);
10 |   if (btnDemo)        btnDemo.addEventListener("click", runDemo);
11 | });
12 | 
13 | // ---------------------------------------------------------------------------
14 | // API calls
15 | // ---------------------------------------------------------------------------
16 | 
17 | async function runDemo() {
18 |   showSpinner();
19 |   try {
20 |     const res  = await fetch("/api/investigate", { method: "POST" });
21 |     const data = await res.json();
22 |     if (data.error) throw new Error(data.error);
23 |     renderReport(data);
24 |   } catch (err) {
25 |     showError(err.message);
26 |   }
27 | }
28 | 
29 | async function runInvestigation() {
30 |   showSpinner();
31 | 
32 |   const formData = new FormData();
33 |   const observation = val("observation");
34 |   const github_url  = val("github_repo_url");
35 | 
36 |   if (!observation && !github_url) {
37 |     const logFile    = document.getElementById("logs")    && document.getElementById("logs").files[0];
38 |     const sourceFile = document.getElementById("source_zip") && document.getElementById("source_zip").files[0];
39 |     if (!logFile && !sourceFile && !observation && !github_url) {
40 |       showError("Please provide at least one piece of evidence before running an investigation.");
41 |       return;
42 |     }
43 |   }
44 | 
45 |   if (observation)  formData.append("observation",     observation);
46 |   if (github_url)   formData.append("github_repo_url", github_url);
47 | 
48 |   const logFile    = document.getElementById("logs")        ? document.getElementById("logs").files[0]        : null;
49 |   const sourceFile = document.getElementById("source_zip")  ? document.getElementById("source_zip").files[0]  : null;
50 |   if (logFile)    formData.append("logs",        logFile);
51 |   if (sourceFile) formData.append("source_zip",  sourceFile);
52 | 
53 |   try {
54 |     // Step 1: create investigation
55 |     const createRes = await fetch("/api/investigations", { method: "POST", body: formData });
56 |     const createData = await createRes.json();
57 |     if (!createRes.ok) throw new Error(createData.error || "Failed to create investigation.");
58 | 
59 |     const investigationId = createData.investigation_id;
60 | 
61 |     // Step 2: run investigation
62 |     const runRes  = await fetch(`/api/investigations/${investigationId}/run`, { method: "POST" });
63 |     const runData = await runRes.json();
64 |     if (!runRes.ok) throw new Error(runData.error || "Investigation failed.");
65 | 
66 |     renderReport(runData);
67 |   } catch (err) {
68 |     showError(err.message);
69 |   }
70 | }
71 | 
72 | // ---------------------------------------------------------------------------
73 | // Report rendering
74 | // ---------------------------------------------------------------------------
75 | 
76 | function renderReport(d) {
77 |   const panel = document.getElementById("report");
78 |   panel.innerHTML = `
79 |     ${renderPipeline()}
80 |     ${renderIncidentHeader(d)}
81 |     ${renderInvestigators(d.investigators)}
82 |     ${renderTribunal(d.tribunal)}
83 |     ${renderVerdict(d.tribunal && d.tribunal.judge)}
84 |     ${renderActions(d.recommended_actions)}
85 |   `;
86 |   setButtons(false);
87 | }
88 | 
89 | function renderPipeline() {
90 |   const steps = ["Incident", "Evidence", "Tribunal", "Verdict", "Proof"];
91 |   return `<div class="pipeline">${steps.map(s => `<div class="step done">${s}</div>`).join("")}</div>`;
92 | }
93 | 
94 | function renderIncidentHeader(d) {
95 |   const inc = d.incident || {};
96 |   return `
97 |     <div class="card">
98 |       <div class="card-title">Incident</div>
99 |       <p><strong>${esc(inc.title || inc.service || "Investigation")}</strong></p>
100 |       <p style="margin-top:6px;font-size:13px;color:#94a3b8">${esc(inc.description || inc.error_summary || "")}</p>
101 |       <p style="margin-top:8px;font-size:12px;color:#64748b">
102 |         Service: ${esc(inc.service || "—")} &nbsp;·&nbsp;
103 |         Severity: ${esc(inc.severity || "—")} &nbsp;·&nbsp;
104 |         Mode: <span style="color:#a78bfa">${esc(d.mode || "user")}</span>
105 |       </p>
106 |     </div>`;
107 | }
108 | 
109 | function renderInvestigators(investigators) {
110 |   if (!investigators || !investigators.length) return "";
111 |   const cards = investigators.map(inv => {
112 |     const pct = Math.round((inv.confidence || 0) * 100);
113 |     const statusColor = inv.status === "complete" ? "#4ade80" : "#f87171";
114 |     return `
115 |       <div class="evidence-card">
116 |         <div class="eid" style="color:${statusColor}">${esc(inv.agent)}</div>
117 |         <div style="font-size:11px;color:#64748b;margin-bottom:6px">${esc(inv.status)}</div>
118 |         ${(inv.findings || []).map(f => `<div class="finding" style="font-size:12px;margin-bottom:3px">· ${esc(f)}</div>`).join("")}
119 |         <div class="conf-bar" style="margin-top:8px">
120 |           <div class="conf-fill" style="width:${pct}%"></div>
121 |         </div>
122 |         <div style="font-size:11px;color:#475569;margin-top:4px">confidence ${pct}%</div>
123 |       </div>`;
124 |   }).join("");
125 |   return `
126 |     <div class="card">
127 |       <div class="card-title">Investigators (Parallel)</div>
128 |       <div class="evidence-grid">${cards}</div>
129 |     </div>`;
130 | }
131 | 
132 | function renderTribunal(tribunal) {
133 |   if (!tribunal) return "";
134 |   const p = tribunal.prosecutor || {};
135 |   const d = tribunal.defense    || {};
136 |   return `
137 |     <div class="card">
138 |       <div class="card-title">Tribunal</div>
139 |       <div class="tribunal-grid">
140 |         <div>
141 |           <div class="role-label role-prosecutor">⚖ Prosecutor</div>
142 |           <p style="font-size:13px;margin-bottom:6px"><strong>${esc(p.position || "")}</strong></p>
143 |           <p style="font-size:12px;color:#94a3b8">${esc(p.argument || "")}</p>
144 |         </div>
145 |         <div class="tribunal-divider"></div>
146 |         <div>
147 |           <div class="role-label role-defense">🛡 Defense</div>
148 |           <p style="font-size:13px;margin-bottom:6px"><strong>${esc(d.argument || "")}</strong></p>
149 |           <ul style="margin-top:8px;padding-left:16px;font-size:11px;color:#64748b">
150 |             ${(d.missing_evidence || []).map(w => `<li>${esc(w)}</li>`).join("")}
151 |           </ul>
152 |         </div>
153 |       </div>
154 |     </div>`;
155 | }
156 | 
157 | function renderVerdict(verdict) {
158 |   if (!verdict) return "";
159 |   const status = verdict.verdict || "UNKNOWN";
160 |   const statusClass = {
161 |     "CONFIRMED":             "verdict-CONFIRMED",
162 |     "MOST_LIKELY":           "verdict-MOST_LIKELY",
163 |     "MORE_EVIDENCE_NEEDED":  "verdict-MORE_EVIDENCE_NEEDED",
164 |     "REJECTED":              "verdict-REJECTED",
165 |   }[status] || "verdict-MORE_EVIDENCE_NEEDED";
166 | 
167 |   const steps = (verdict.recommended_next_steps || [])
168 |     .map(s => `<li>${esc(s)}</li>`).join("");
169 | 
170 |   return `
171 |     <div class="card">
172 |       <div class="card-title">Verdict — Judge</div>
173 |       <div class="verdict-badge ${statusClass}">${status.replace(/_/g, " ")}</div>
174 |       <p style="font-weight:600;margin-bottom:8px">${esc(verdict.leading_hypothesis || "")}</p>
175 |       <p style="font-size:13px;color:#94a3b8">${esc(verdict.best_current_assessment || verdict.reason || "")}</p>
176 |       <p style="font-size:12px;color:#475569;margin-top:8px">
177 |         Confidence: <strong>${esc(verdict.confidence_level || "")}</strong>
178 |       </p>
179 |       ${steps ? `<ul class="actions-list" style="margin-top:12px">${steps}</ul>` : ""}
180 |     </div>`;
181 | }
182 | 
183 | function renderActions(actions) {
184 |   if (!actions) return "";
185 |   const all = [
186 |     ...(actions.high_priority   || []),
187 |     ...(actions.medium_priority || []),
188 |     ...(actions.optional        || []),
189 |   ];
190 |   if (!all.length) return "";
191 |   const items = all.map(a => `<li><strong>[${esc(a.priority)}]</strong> ${esc(a.action)}</li>`).join("");
192 |   return `
193 |     <div class="card">
194 |       <div class="card-title">Recommended Actions</div>
195 |       <ul class="actions-list">${items}</ul>
196 |     </div>`;
197 | }
198 | 
199 | // ---------------------------------------------------------------------------
200 | // UI helpers
201 | // ---------------------------------------------------------------------------
202 | 
203 | function showSpinner() {
204 |   const panel = document.getElementById("report");
205 |   panel.innerHTML = `
206 |     <div id="spinner" class="active">
207 |       <div class="spin-ring"></div>
208 |       <span style="color:#64748b;font-size:13px">Running investigation…</span>
209 |     </div>`;
210 |   setButtons(true);
211 | }
212 | 
213 | function showError(msg) {
214 |   document.getElementById("report").innerHTML = `
215 |     <div class="card" style="border-color:#7f1d1d">
216 |       <div class="card-title" style="color:#f87171">Error</div>
217 |       <p style="color:#fca5a5">${esc(msg)}</p>
218 |     </div>`;
219 |   setButtons(false);
220 | }
221 | 
222 | function setButtons(disabled) {
223 |   ["btn-investigate", "btn-demo"].forEach(id => {
224 |     const el = document.getElementById(id);
225 |     if (el) el.disabled = disabled;
226 |   });
227 | }
228 | 
229 | function esc(str) {
230 |   if (str === null || str === undefined) return "";
231 |   return String(str)
232 |     .replace(/&/g, "&amp;")
233 |     .replace(/</g, "&lt;")
234 |     .replace(/>/g, "&gt;")
235 |     .replace(/"/g, "&quot;");
236 | }
237 | 
238 | function val(id) {
239 |   const el = document.getElementById(id);
240 |   return el ? (el.value || "").trim() : "";
241 | }
